changeSet.sql:
ALTER TABLE household ADD COLUMN location_geom geometry(Point, 4326)
  GENERATED ALWAYS AS (
    CASE WHEN latitude BETWEEN -90 AND 90 AND longitude BETWEEN -180 AND 180
           AND latitude != 0 AND longitude != 0
         THEN ST_SetSRID(ST_MakePoint(longitude, latitude), 4326)
         ELSE NULL END
  ) STORED;
CREATE INDEX ix_household_location_geom ON household USING GIST (location_geom);
ALTER TABLE gis_building ADD COLUMN footprint_geom geometry(MultiPolygon, 4326);
CREATE INDEX ix_gis_building_footprint_geom ON gis_building USING GIST (footprint_geom);
ALTER TABLE gis_road ADD COLUMN line_geom geometry(MultiLineString, 4326);
CREATE INDEX ix_gis_road_line_geom ON gis_road USING GIST (line_geom);
